import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"斜杠命令","description":"","frontmatter":{},"headers":[],"relativePath":"reference/slash-commands.md","filePath":"reference/slash-commands.md"}'),r={name:"reference/slash-commands.md"};function c(l,t,h,n,i,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h1><p>在 nek 的输入框里输入 <code>/</code> 可以搜索当前会话可用的命令。这一页列出内置命令。扩展、提示词模板和 Skills 也会添加命令，所以 <code>/</code> 菜单才是你当前会话的准确清单。</p><h2 id="模型与设置" tabindex="-1">模型与设置 <a class="header-anchor" href="#模型与设置" aria-label="Permalink to &quot;模型与设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/settings</code></td><td>打开设置</td></tr><tr><td><code>/model [服务商/模型]</code></td><td>选择模型；带参数时直接切换</td></tr><tr><td><code>/thinking [等级]</code></td><td>设置思考等级</td></tr><tr><td><code>/scoped-models</code></td><td>设置 <code>Ctrl+P</code> 循环使用的模型</td></tr><tr><td><code>/login [服务商]</code></td><td>添加服务商认证</td></tr><tr><td><code>/logout</code></td><td>删除服务商认证</td></tr></tbody></table><h2 id="plan、todo-与子代理" tabindex="-1">Plan、Todo 与子代理 <a class="header-anchor" href="#plan、todo-与子代理" aria-label="Permalink to &quot;Plan、Todo 与子代理&quot;">​</a></h2><p>这些命令由内置的 nek 扩展提供。</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/plan</code></td><td>安静地进入 Plan 模式</td></tr><tr><td><code>/plan &lt;需求&gt;</code></td><td>进入 Plan 模式并提交规划或修订请求</td></tr><tr><td><code>/agent</code></td><td>退出 Plan 模式，不开始实施</td></tr><tr><td><code>/plans</code></td><td>选择并预览一份已保存的计划</td></tr><tr><td><code>/nek-build [plan_id] [--fresh]</code></td><td>批准并实施一份已审阅的计划修订版本；<code>--fresh</code> 在新会话中实施</td></tr><tr><td><code>/todos</code></td><td>显示当前分支的 Todo 列表</td></tr><tr><td><code>/subagents</code></td><td>列出子代理、查看结果、取消运行中的子代理</td></tr><tr><td><code>/agents</code></td><td>列出可用的子代理类型</td></tr></tbody></table><p>见 <a href="/nekcode/guide/plan-mode">Plan 模式</a>、<a href="/nekcode/guide/todos">Todo 列表</a>、<a href="/nekcode/guide/subagents">子代理</a>。</p><h2 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to &quot;会话与上下文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/new</code></td><td>开始新会话</td></tr><tr><td><code>/resume</code></td><td>切换到另一个已保存的会话</td></tr><tr><td><code>/name [名字]</code></td><td>设置会话显示名；不带参数时显示当前名字</td></tr><tr><td><code>/session</code></td><td>显示会话信息和统计</td></tr><tr><td><code>/tree</code></td><td>浏览会话树，切换分支</td></tr><tr><td><code>/fork</code></td><td>从较早的一条用户消息创建新会话</td></tr><tr><td><code>/clone</code></td><td>在当前位置复制当前会话</td></tr><tr><td><code>/compact [说明]</code></td><td>手动压缩上下文，可附带说明指引摘要重点</td></tr><tr><td><code>/import &lt;路径&gt;</code></td><td>导入并打开一个 JSONL 会话</td></tr></tbody></table><h2 id="导出与分享" tabindex="-1">导出与分享 <a class="header-anchor" href="#导出与分享" aria-label="Permalink to &quot;导出与分享&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/copy</code></td><td>复制最后一条助手消息</td></tr><tr><td><code>/export [路径]</code></td><td>导出会话为 HTML（默认）或 JSONL（路径以 <code>.jsonl</code> 结尾）</td></tr><tr><td><code>/share</code></td><td>上传会话并返回查看链接（Radius，或通过 GitHub CLI 创建私密 gist）</td></tr></tbody></table><p>导出或分享前请检查会话内容，里面可能有提示词、工具参数、命令输出、文件内容和对话中出现过的凭据。</p><h2 id="运行环境与项目" tabindex="-1">运行环境与项目 <a class="header-anchor" href="#运行环境与项目" aria-label="Permalink to &quot;运行环境与项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/mcp [login|logout|reconnect] [服务器]</code></td><td>管理 <a href="/nekcode/guide/mcp">MCP 服务器</a>：连接、暴露方式、OAuth</td></tr><tr><td><code>/trust</code></td><td>保存当前项目的信任决定，供以后的 nek 进程使用</td></tr><tr><td><code>/reload</code></td><td>重新加载快捷键、扩展、Skills、模板、主题和指令文件</td></tr><tr><td><code>/hotkeys</code></td><td>显示当前生效的快捷键</td></tr><tr><td><code>/changelog</code></td><td>显示更新日志</td></tr><tr><td><code>/debug</code></td><td>把渲染的终端行和会话消息写到 <code>~/.nek/agent/nek-debug.log</code></td></tr><tr><td><code>/quit</code></td><td>退出 nek</td></tr></tbody></table><h2 id="资源添加的命令" tabindex="-1">资源添加的命令 <a class="header-anchor" href="#资源添加的命令" aria-label="Permalink to &quot;资源添加的命令&quot;">​</a></h2><ul><li>扩展可以注册带参数和补全的命令；</li><li>每个提示词模板以文件名作为命令名，见 <a href="/nekcode/customize/prompt-templates">提示词模板</a>；</li><li>Skills 在启用 Skill 命令时以 <code>/skill:名字</code> 出现，见 <a href="/nekcode/customize/skills">Skills</a>。</li></ul><p>添加或修改这类资源后运行 <code>/reload</code>。</p><h2 id="输入框里的其他前缀" tabindex="-1">输入框里的其他前缀 <a class="header-anchor" href="#输入框里的其他前缀" aria-label="Permalink to &quot;输入框里的其他前缀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>作用</th></tr></thead><tbody><tr><td><code>!命令</code></td><td>执行 shell 命令，输出加入对话</td></tr><tr><td><code>!!命令</code></td><td>执行 shell 命令，输出不发给模型</td></tr><tr><td><code>@文件</code></td><td>模糊搜索并引用文件</td></tr></tbody></table>',20)])])}const m=d(r,[["render",c]]);export{u as __pageData,m as default};
